1	#!/usr/bin/env node
2	// Simulated users for one environment (SDLC-6, Maintain). The todo app has no server, so there is no 5xx rate to watch.
3	// The stand-in: simulated users run the app's own logic (store.js + backup.js of the release that is live in <env>) and
4	// we count the actions that fail from the user's side. This is SIMULATED traffic, not real users.
5	//
6	//   node scripts/traffic.js --release <dir> --state <file.json> --seed <n> [--users 40] [--fault 0.01]
7	//
8	// One run = one simulated day. Each user keeps their browser storage in <state> between days (so a bad release that
9	// writes something wrong today breaks tomorrow's session, as it would for a real person).
10	// A failed action is one of:
11	//   - not_saved      persist() told the user "not saved" (storage refused the write)
12	//   - import_failed  the user backed up to a file and imported that same file back, and the app refused it
13	//   - exception      the app code threw
14	// Storage refuses a write with probability --fault (the browser quota, a private window...). That is the normal noise.
15	// Prints one JSON line: { actions, failed, rate, by_kind, users, release }.
16	'use strict';
17	const fs = require('node:fs');
18	const path = require('node:path');
19	
20	function arg(name, dflt) {
21	  const i = process.argv.indexOf(name);
22	  return i >= 0 ? process.argv[i + 1] : dflt;
23	}
24	
25	// Small deterministic PRNG (mulberry32): the same seed gives the same day.
26	function rng(seed) {
27	  let a = seed >>> 0;
28	  return () => {
29	    a = (a + 0x6d2b79f5) >>> 0;
30	    let t = a;
31	    t = Math.imul(t ^ (t >>> 15), t | 1);
32	    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
33	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
34	  };
35	}
36	
37	const release = path.resolve(arg('--release'));
38	const stateFile = arg('--state');
39	const rand = rng(Number(arg('--seed', '1')));
40	const USERS = Number(arg('--users', '40'));
41	const FAULT = Number(arg('--fault', '0.01'));
42	
43	const { store, STORE_KEY } = require(path.join(release, 'store.js'));
44	const backup = require(path.join(release, 'backup.js'));
45	
46	const state = stateFile && fs.existsSync(stateFile) ? JSON.parse(fs.readFileSync(stateFile, 'utf8')) : {};
47	const WORDS = ['Mua sữa', 'Gọi mẹ', 'Nộp báo cáo', 'Đặt vé', 'Trả tiền điện', 'Đọc sách', 'Tập thể dục', 'Sửa xe', 'Họp nhóm'];
48	
49	function storageFor(user) {
50	  const data = state[user] || {};
51	  state[user] = data;
52	  return {
53	    getItem: (k) => (Object.prototype.hasOwnProperty.call(data, k) ? data[k] : null),
54	    setItem: (k, v) => {
55	      if (rand() < FAULT) {
56	        const e = new Error('quota');
57	        e.name = 'QuotaExceededError';
58	        throw e;
59	      }
60	      data[k] = String(v);
61	    },
62	  };
63	}
64	
65	let actions = 0;
66	let failed = 0;
67	const byKind = { not_saved: 0, import_failed: 0, exception: 0 };
68	const fail = (kind) => {
69	  failed++;
70	  byKind[kind]++;
71	};
72	
73	async function session(user, day) {
74	  globalThis.localStorage = storageFor(user);
75	  let todos = store.load().todos;
76	  const n = 3 + Math.floor(rand() * 6);
77	  for (let i = 0; i < n; i++) {
78	    const r = rand();
79	    actions++;
80	    try {
81	      if (r < 0.45 || todos.length === 0) {
82	        const t = { id: `${user}-${day}-${i}`, title: WORDS[Math.floor(rand() * WORDS.length)], done: false,
83	          createdAt: Date.UTC(2026, 9, 1) + day * 86400000 + i };
84	        todos = [...todos, t];
85	        if (backup.persist(store, todos).message) fail('not_saved');
86	      } else if (r < 0.72) {
87	        const k = Math.floor(rand() * todos.length);
88	        todos = todos.map((t, j) => (j === k ? { ...t, done: !t.done } : t));
89	        if (backup.persist(store, todos).message) fail('not_saved');
90	      } else if (r < 0.85) {
91	        const k = Math.floor(rand() * todos.length);
92	        todos = todos.filter((_, j) => j !== k);
93	        if (backup.persist(store, todos).message) fail('not_saved');
94	      } else {
95	        // Back up to a file, then import that same file (for example on a new laptop).
96	        const text = backup.toBackupText(todos);
97	        const file = { size: Buffer.byteLength(text), text: async () => text };
98	        const out = await backup.importBackup({ store, current: todos, file, ask: async () => true });
99	        const ok = out.message && out.message.startsWith('Đã nhập');
100	        if (ok) todos = out.todos;
101	        else fail('import_failed');
102	      }
103	    } catch {
104	      fail('exception');
105	    }
106	  }
107	}
108	
109	(async () => {
110	  const day = Number(arg('--day', '0'));
111	  for (let u = 0; u < USERS; u++) await session(`u${String(u).padStart(2, '0')}`, day);
112	  if (stateFile) fs.writeFileSync(stateFile, JSON.stringify(state));
113	  let rel = null;
114	  try {
115	    rel = JSON.parse(fs.readFileSync(path.join(release, 'RELEASE.json'), 'utf8')).id;
116	  } catch {}
117	  console.log(JSON.stringify({ actions, failed, rate: actions ? failed / actions : 0, by_kind: byKind, users: USERS, release: rel,
118	    key: STORE_KEY }));
119	})();
