'use strict';
// Read-only: look for duplicate ids / invalid todos in the simulated users' storage.
const fs = require('node:fs');
const s = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
let users = 0, total = 0;
const days = {};
for (const [u, data] of Object.entries(s)) {
  users++;
  const raw = data['todo.v1'];
  if (raw == null) continue;
  let list;
  try { list = JSON.parse(raw); } catch { console.log(u, 'unparsable'); continue; }
  total += list.length;
  const seen = new Map();
  for (const t of list) {
    const d = t.id.split('-')[1];
    days[d] = (days[d] || 0) + 1;
    seen.set(t.id, (seen.get(t.id) || 0) + 1);
    if (typeof t.title !== 'string' || !t.title.trim()) console.log(u, 'bad title', t.id);
  }
  const dups = [...seen].filter(([, n]) => n > 1);
  if (dups.length) console.log(u, 'dup ids', JSON.stringify(dups));
}
console.log('users', users, 'todos', total, 'by day', JSON.stringify(days));

